#!/usr/bin/env node

// Compiles the built-in themes and snippets in native/macos/Themes into
// native/macos/Sources/RoachNetDesign/Theme/RoachBuiltInThemes.generated.swift.
//
// The JSON files are the source of truth. The app embeds them as strings so
// RoachNetDesign needs no resource bundle. Run with --check to fail when the
// generated file is out of date (the test suite does).

import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const themesRoot = path.join(repoRoot, 'native/macos/Themes')
const outputPath = path.join(repoRoot, 'native/macos/Sources/RoachNetDesign/Theme/RoachBuiltInThemes.generated.swift')

const THEME_SCHEMA = 'org.roachnet.theme.v1'
const SNIPPET_SCHEMA = 'org.roachnet.theme-snippet.v1'
const TOKENS = new Set([
  'accent', 'accentSecondary', 'accentTertiary', 'accentInfo', 'background', 'backgroundRaised', 'panel', 'panelRaised',
  'panelSoft', 'glass', 'specular', 'border', 'borderStrong', 'text', 'muted', 'success', 'warning', 'danger', 'shadow',
  'ink', 'shade', 'onAccent',
])
const STYLES = new Set(['signal', 'grid', 'circuit', 'aurora', 'starfield', 'scanlines', 'particles', 'paper', 'solid', 'image'])
const COLOR = /^(#([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})|rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*(,\s*(0|1|0?\.\d+)\s*)?\))$/i
const ID = /^[a-z0-9][a-z0-9._-]{1,63}$/

function fail(message) {
  console.error(`generate-builtin-themes: ${message}`)
  process.exit(1)
}

function checkMode(file, label, mode) {
  if (!mode) return
  for (const [key, value] of Object.entries(mode.palette ?? {})) {
    if (!TOKENS.has(key)) fail(`${file}: ${label} uses unknown token ${key}`)
    if (!COLOR.test(value)) fail(`${file}: ${label}.${key} is not a color: ${value}`)
  }
  const background = mode.background
  if (background?.style && !STYLES.has(background.style)) fail(`${file}: ${label} uses unknown background style ${background.style}`)
  for (const value of background?.colors ?? []) {
    if (!COLOR.test(value)) fail(`${file}: ${label}.background.colors has a non-color: ${value}`)
  }
}

function load(folder, suffix, schema) {
  const directory = path.join(themesRoot, folder)
  const ids = new Set()
  return readdirSync(directory)
    .filter((name) => name.endsWith(suffix))
    .sort()
    .map((name) => {
      const file = `${folder}/${name}`
      const text = readFileSync(path.join(directory, name), 'utf8')
      let document
      try {
        document = JSON.parse(text)
      } catch (error) {
        fail(`${file}: ${error.message}`)
      }
      if (document.schema !== schema) fail(`${file}: schema must be ${schema}`)
      if (!ID.test(document.id ?? '')) fail(`${file}: bad id ${document.id}`)
      if (ids.has(document.id)) fail(`${file}: duplicate id ${document.id}`)
      ids.add(document.id)
      if (!document.name?.trim()) fail(`${file}: needs a name`)
      if (schema === THEME_SCHEMA && !document.dark && !document.light) fail(`${file}: needs a dark or light mode`)
      for (const label of ['all', 'dark', 'light']) checkMode(file, label, document[label])
      const compact = JSON.stringify(document)
      if (compact.includes('"##')) fail(`${file}: contains "## which the Swift raw string cannot hold`)
      return { id: document.id, name: document.name, compact }
    })
}

const themes = load('builtin', '.roachtheme.json', THEME_SCHEMA)
const snippets = load('snippets', '.roachsnippet.json', SNIPPET_SCHEMA)
if (!themes.some((theme) => theme.id === 'roachnet.signal')) fail('the Signal theme (roachnet.signal) must exist')
// Signal first, then by name.
themes.sort((a, b) => (a.id === 'roachnet.signal' ? -1 : b.id === 'roachnet.signal' ? 1 : a.name.localeCompare(b.name)))
snippets.sort((a, b) => a.name.localeCompare(b.name))

function literal(items) {
  return items.map((item) => `        ##"${item.compact}"##,`).join('\n')
}

const output = `// Generated by scripts/generate-builtin-themes.mjs from native/macos/Themes.
// Do not edit: change the JSON and run \`npm run native:themes\`.

enum RoachBuiltInThemeSources {
    /// ${themes.length} themes, Signal first.
    static let themes: [String] = [
${literal(themes)}
    ]

    /// ${snippets.length} snippets.
    static let snippets: [String] = [
${literal(snippets)}
    ]
}
`

if (process.argv.includes('--check')) {
  let current = ''
  try {
    current = readFileSync(outputPath, 'utf8')
  } catch {}
  if (current !== output) fail('RoachBuiltInThemes.generated.swift is out of date; run npm run native:themes')
  console.log(`Built-in themes are current: ${themes.length} themes, ${snippets.length} snippets.`)
} else {
  writeFileSync(outputPath, output)
  console.log(`Wrote ${path.relative(repoRoot, outputPath)}: ${themes.length} themes, ${snippets.length} snippets.`)
}
